sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Store the reservation status as a string for clean comparison
    var reservationStatus = current.reservation_status.toString();

    // Pending check-in and checked-in both map to the OOB Open state
    if (reservationStatus == 'pending_check_in' || reservationStatus == 'checked_in') {
        current.state = 1;
    }
    // No-show and cancelled map to Closed Skipped
    else if (reservationStatus == 'no_show' || reservationStatus == 'cancelled') {
        current.state = 7;
    }
    // Checked-out maps to Closed Complete
    else if (reservationStatus == 'checked_out') {
        current.state = 3;
    }

    // No current.update() here — this is a before rule, so ServiceNow
    // automatically saves this change when the record commits.
    // Calling update() here would trigger a redundant save and re-fire business rules.

})(current, previous);
